  `created_at` datetime NULL DEFAULT NULL,
  `updated_at` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `chemical_stock_movements_warehouse_id_foreign`(`warehouse_id` ASC) USING BTREE,
  INDEX `chemical_stock_movements_created_by_foreign`(`created_by` ASC) USING BTREE,
  INDEX `period_id_warehouse_id_chemical_id`(`period_id` ASC, `warehouse_id` ASC, `chemical_id` ASC) USING BTREE,
  INDEX `chemical_id`(`chemical_id` ASC) USING BTREE,
  INDEX `variant_id`(`variant_id` ASC) USING BTREE,
  INDEX `movement_type`(`movement_type` ASC) USING BTREE,
  INDEX `reference_type_reference_id`(`reference_type` ASC, `reference_id` ASC) USING BTREE,
  INDEX `movement_date`(`movement_date` ASC) USING BTREE,
  CONSTRAINT `chemical_stock_movements_chemical_id_foreign` FOREIGN KEY (`chemical_id`) REFERENCES `chemicals` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chemical_stock_movements_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `chemical_stock_movements_period_id_foreign` FOREIGN KEY (`period_id`) REFERENCES `periods` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chemical_stock_movements_variant_id_foreign` FOREIGN KEY (`variant_id`) REFERENCES `chemical_variants` (`id`) ON DELETE CASCADE ON UPDATE SET NULL,
  CONSTRAINT `chemical_stock_movements_warehouse_id_foreign` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouses` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

