-- ----------------------------
-- Table structure for formulation_items
-- ----------------------------
DROP TABLE IF EXISTS `formulation_items`;
CREATE TABLE `formulation_items`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `formulation_version_id` int UNSIGNED NOT NULL,
  `chemical_id` int UNSIGNED NULL DEFAULT NULL,
  `composition_type` enum('chemical','softener_water') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'chemical' COMMENT 'chemical = konsumsi stok bahan kimia, softener_water = tanpa alur stok',
  `variant_id` int UNSIGNED NULL DEFAULT NULL,
  `custom_label` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Nama bebas untuk softener_water, mis. \"Air Proses/Softening\"',
  `percentage` decimal(8, 3) NOT NULL DEFAULT 0.000 COMMENT 'Dosis dalam % terhadap berat batch, tidak dibatasi total 100%',
  `unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `notes` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT 0,
  `created_at` datetime NULL DEFAULT NULL,
  `updated_at` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `formulation_version_id_chemical_id`(`formulation_version_id` ASC, `chemical_id` ASC) USING BTREE,
  INDEX `formulation_version_id`(`formulation_version_id` ASC) USING BTREE,
  INDEX `chemical_id`(`chemical_id` ASC) USING BTREE,
  INDEX `variant_id`(`variant_id` ASC) USING BTREE,
  INDEX `composition_type`(`composition_type` ASC) USING BTREE,
  CONSTRAINT `formulation_items_chemical_id_foreign` FOREIGN KEY (`chemical_id`) REFERENCES `chemicals` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `formulation_items_formulation_version_id_foreign` FOREIGN KEY (`formulation_version_id`) REFERENCES `formulation_versions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `formulation_items_variant_id_foreign` FOREIGN KEY (`variant_id`) REFERENCES `chemical_variants` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 2819 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of formulation_items
-- ----------------------------

-- ----------------------------
-- Table structure for formulation_stock_movements
-- ----------------------------
DROP TABLE IF EXISTS `formulation_stock_movements`;
CREATE TABLE `formulation_stock_movements`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `period_id` int UNSIGNED NOT NULL,
  `warehouse_id` int UNSIGNED NOT NULL,
  `formulation_id` int UNSIGNED NOT NULL,
  `formulation_version_id` int UNSIGNED NULL DEFAULT NULL COMMENT 'Versi resep yang berlaku saat transaksi ini dicatat — dipakai untuk breakdown kimia penyusun',
  `movement_type` enum('MixingIn','AppliedOut','TransferIn','TransferOut','AdjustmentIn','AdjustmentOut') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'MixingIn & AppliedOut disiapkan untuk modul mixing/aplikasi produksi menyusul',
  `quantity_in` decimal(15, 3) NOT NULL DEFAULT 0.000,
  `quantity_out` decimal(15, 3) NOT NULL DEFAULT 0.000,
  `unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `reference_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Sumber transaksi: stock_transfer, stock_adjustment, manual, dll',
  `reference_id` int UNSIGNED NULL DEFAULT NULL,
  `movement_date` date NOT NULL,
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `created_by` int UNSIGNED NULL DEFAULT NULL,
  `created_at` datetime NULL DEFAULT NULL,
  `updated_at` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `formulation_stock_movements_warehouse_id_foreign`(`warehouse_id` ASC) USING BTREE,
  INDEX `formulation_stock_movements_created_by_foreign`(`created_by` ASC) USING BTREE,
  INDEX `period_id_warehouse_id_formulation_id`(`period_id` ASC, `warehouse_id` ASC, `formulation_id` ASC) USING BTREE,
  INDEX `formulation_id`(`formulation_id` ASC) USING BTREE,
  INDEX `movement_type`(`movement_type` ASC) USING BTREE,
  INDEX `reference_type_reference_id`(`reference_type` ASC, `reference_id` ASC) USING BTREE,
  INDEX `movement_date`(`movement_date` ASC) USING BTREE,
  INDEX `idx_fsm_version`(`formulation_version_id` ASC) USING BTREE,
  CONSTRAINT `formulation_stock_movements_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `formulation_stock_movements_formulation_id_foreign` FOREIGN KEY (`formulation_id`) REFERENCES `formulations` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `formulation_stock_movements_formulation_version_id_foreign` FOREIGN KEY (`formulation_version_id`) REFERENCES `formulation_versions` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `formulation_stock_movements_period_id_foreign` FOREIGN KEY (`period_id`) REFERENCES `periods` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `formulation_stock_movements_warehouse_id_foreign` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouses` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of formulation_stock_movements
-- ----------------------------

