  `created_by` int UNSIGNED NULL DEFAULT NULL,
  `updated_by` int UNSIGNED NULL DEFAULT NULL,
  `created_at` datetime NULL DEFAULT NULL,
  `updated_at` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_fso2_period_wh_formulation_version`(`period_id` ASC, `warehouse_id` ASC, `formulation_id` ASC, `formulation_version_id` ASC) USING BTREE,
  INDEX `formulation_stock_opnames_created_by_foreign`(`created_by` ASC) USING BTREE,
  INDEX `formulation_stock_opnames_updated_by_foreign`(`updated_by` ASC) USING BTREE,
  INDEX `period_id`(`period_id` ASC) USING BTREE,
  INDEX `warehouse_id`(`warehouse_id` ASC) USING BTREE,
  INDEX `formulation_id`(`formulation_id` ASC) USING BTREE,
  INDEX `formulation_version_id`(`formulation_version_id` ASC) USING BTREE,
  CONSTRAINT `formulation_stock_opnames_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `formulation_stock_opnames_formulation_id_foreign` FOREIGN KEY (`formulation_id`) REFERENCES `formulations` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `formulation_stock_opnames_formulation_version_id_foreign` FOREIGN KEY (`formulation_version_id`) REFERENCES `formulation_versions` (`id`) ON DELETE CASCADE ON UPDATE SET NULL,
  CONSTRAINT `formulation_stock_opnames_period_id_foreign` FOREIGN KEY (`period_id`) REFERENCES `periods` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `formulation_stock_opnames_updated_by_foreign` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `formulation_stock_opnames_warehouse_id_foreign` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouses` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
