  `variant_id` int UNSIGNED NULL DEFAULT NULL,
  `formulation_id` int UNSIGNED NULL DEFAULT NULL,
  `system_quantity` decimal(15, 3) NOT NULL DEFAULT 0.000 COMMENT 'Stok menurut sistem (hasil sum on-the-fly) saat adjustment dibuat',
  `physical_quantity` decimal(15, 3) NOT NULL DEFAULT 0.000 COMMENT 'Stok fisik hasil stock opname / pengecekan',
  `difference_quantity` decimal(15, 3) NOT NULL DEFAULT 0.000 COMMENT 'physical_quantity - system_quantity (positif = AdjustmentIn, negatif = AdjustmentOut)',
  `unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `notes` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
